  function getNFAnimationPerfProbeSession() {
    const api = window.__NFAnimationPerfProbe
    return api && api.__version && api.current ? api.current : null
  }

  function addNFAnimationPerfCount(key, amount = 1) {
    const session = getNFAnimationPerfProbeSession()
    if (!session || !session.counts) return
    session.counts[key] = (Number(session.counts[key]) || 0) + amount
  }

  function addNFAnimationPerfCallsite(key, label, amount = 1) {
    const session = getNFAnimationPerfProbeSession()
    if (!session) return
    if (!session.callsiteCounts || typeof session.callsiteCounts !== 'object') session.callsiteCounts = {}
    if (!session.callsiteCounts[key] || typeof session.callsiteCounts[key] !== 'object') session.callsiteCounts[key] = {}
    const cleanLabel = String(label || 'unknown').replace(/\s+/g, ' ').trim().slice(0, 160) || 'unknown'
    session.callsiteCounts[key][cleanLabel] = (Number(session.callsiteCounts[key][cleanLabel]) || 0) + amount
  }

  function recordWorkspaceActiveWriterAttempt(writerName, nextValue) {
    if (!(document.body instanceof HTMLElement)) return
    const currentValue = document.body.getAttribute(WORKSPACE_ACTIVE_ATTR)
    const normalizedNextValue = nextValue == null ? null : String(nextValue)
    const changed = currentValue !== normalizedNextValue
    const valueLabel = normalizedNextValue === WORKSPACE_ACTIVE_ATTR_VALUE ? 'true' : normalizedNextValue == null ? 'null' : String(normalizedNextValue)
    addNFAnimationPerfCount('workspaceActiveWriterAttempt')
    addNFAnimationPerfCount(changed ? 'workspaceActiveWriterChanged' : 'workspaceActiveWriterSameValue')
    addNFAnimationPerfCallsite('workspaceActiveWriter', writerName)
    addNFAnimationPerfCallsite('workspaceActiveWriterValue', valueLabel)
    addNFAnimationPerfCallsite('workspaceActiveWriterResult', changed ? 'changed' : 'same-value')
    addNFAnimationPerfCallsite(changed ? 'workspaceActiveWriterChangedByWriter' : 'workspaceActiveWriterSameValueByWriter', writerName)
  }

  function recordWorkspaceActiveWriterSkippedSameValue(writerName) {
    addNFAnimationPerfCount('workspaceActiveWriterSkippedSameValue')
    addNFAnimationPerfCallsite('workspaceActiveWriterGuard', writerName)
  }
