      if (canvas.height !== size.height) canvas.height = size.height
      if (mode === 'selectionTool' && selectionToolSession) drawSelectionPreview(canvas, selectionToolSession)
      if (mode === 'maskEdit' && maskEditorSession) drawMaskEditorPreview(canvas, maskEditorSession)
      if (mode === 'penTool' && penToolSession) drawPenToolPreview(canvas, penToolSession)
