    const buttons = Number(event.buttons) || 0
    if (buttonName === 'left') return !!(buttons & 1)
    if (buttonName === 'right') return !!(buttons & 2) || !!(buttons & 4)
    if (buttonName === 'middle') return !!(buttons & 4)
