      onpointerenter: (event) => routeSplitCanvasToolPointerMove(event, (evt) => continueSelectionPaint(evt, canvas, cursorEl)),
      onpointermove: (event) => routeSplitCanvasToolPointerMove(event, (evt) => continueSelectionPaint(evt, canvas, cursorEl)),
