    const vertical = sideStrength.top + sideStrength.bottom
    if (horizontal + vertical <= 4) return { direction: '', reason: 'detail-direction-insufficient', sideStrength }
    const direction = horizontal >= vertical * 1.18 ? 'horizontal' : (vertical >= horizontal * 1.18 ? 'vertical' : 'mixed')
