      residualR: outR,
      residualG: outG,
      residualB: outB,
      residualL: outL,
      confidence,
      propagatedPixels,
      detailDirection: direction,
      detailRejectedReason: propagatedPixels < Math.max(12, (distanceField.maskPixels || []).length * 0.08) ? 'detail-propagation-insufficient' : '',
