    const style = window.getComputedStyle ? window.getComputedStyle(activeBackground) : activeBackground.style
    const opacity = Number(style && style.opacity)
    if (!rect || rect.width <= 0 || rect.height <= 0) throw new Error('mask entry active background hidden')
    if (!Number.isFinite(opacity) || opacity < 0.95) throw new Error(`mask entry active background not visible: ${style && style.opacity}`)
    document.body.setAttribute('data-novaflow-mask-entry-visible-smoke', `ok:${Math.round(rect.width)}x${Math.round(rect.height)}:${style && style.opacity}`)
