    setMaskFeather(4, false)
    drawMaskEditorPreview(canvas, session)
    assertMaskLiveEffectCanRevealCanvasTransparency(canvas)
    const beforeMask = canvasImageSnapshot(session.maskCanvas)
    const liveCanvas = maskEditorLiveCanvas(canvas)
    const beforeLive = canvasImageSnapshot(liveCanvas)
    const sceneToClient = (x, y) => ({
      clientX: rect.left + (x / Math.max(1, canvas.width)) * rect.width,
      clientY: rect.top + (y / Math.max(1, canvas.height)) * rect.height
    })
    const start = sceneToClient(Number(session.partX || 0) + Math.max(2, Number(session.width || 1) * 0.42), Number(session.partY || 0) + Math.max(2, Number(session.height || 1) * 0.52))
    const end = sceneToClient(Number(session.partX || 0) + Math.max(2, Number(session.width || 1) * 0.66), Number(session.partY || 0) + Math.max(2, Number(session.height || 1) * 0.54))
