    if (maskPartPersistenceSignature(state.parts.find((item) => item && item.id === part.id)) !== beforePartSignature) throw new Error('mask ctrl+z changed persisted part before Apply')
    if (maskPartPersistenceSignature((activeSplitSet() && activeSplitSet().parts || []).find((item) => item && item.id === part.id)) !== beforeSetPartSignature) throw new Error('mask ctrl+z changed active split set before Apply')
