    const canvas = activeMaskToolCanvas()
    if (!canvas) throw new Error('mask cold quick canvas missing')
    const rect = canvas.getBoundingClientRect()
    if (!rect || rect.width <= 0 || rect.height <= 0) throw new Error('mask cold quick canvas hidden')
    assertMaskCanvasAboveLayerImages(canvas)
    const part = maskEditorPart()
    const warmSession = maskEditorSession || await ensureMaskEditorSession(part)
    if (!warmSession) throw new Error('mask cold quick baseline session missing')
    state.maskEditor.mode = 'erase'
    setMaskBrushSize(30, false)
    setMaskFeather(6, false)
    drawMaskEditorPreview(canvas, warmSession)
    assertMaskLiveEffectCanRevealCanvasTransparency(canvas)
    const beforeMask = canvasImageSnapshot(warmSession.maskCanvas)
    const persistedSignature = (item) => JSON.stringify([
      String(item && item.dataUrl || ''),
      String(item && item.maskDataUrl || ''),
      String(item && layerImageDataUrl(item) || ''),
      String(item && layerMaskDataUrl(item) || '')
    ])
    const beforePartSignature = persistedSignature(part)
    const beforeSetPart = (activeSplitSet() && activeSplitSet().parts || []).find((item) => item && item.id === (part && part.id))
    const beforeSetPartSignature = persistedSignature(beforeSetPart)
