    await paintSelectionStrokeOnActiveSplitCanvas('cutout')
    await assertSelectionUndoSmoke('cutout')
    await movePointerOnActiveSplitCanvas()
    await assertSelectionCursorVisible('cutout after paint')
    await assertBrushCursorHiddenOutsideCanvas('cutout', '[data-novaflow-selection-brush-cursor="1"]')
    await clickSplitToolActionForSmoke('viewSource')
    if (state.selectionTool && state.selectionTool.active) throw new Error('source view did not exit AI cutout')
    if (state.viewMode !== 'source') throw new Error(`source view after cutout failed: ${state.viewMode}`)

    setLayerSelection(partB.id)
    executeInpaintTool()
    await new Promise((resolve) => window.setTimeout(resolve, 160))
    if (!state.selectionTool || !state.selectionTool.active || state.selectionTool.mode !== 'inpaint') throw new Error('AI inpaint did not enter brush mode')
    assertNoVisibleSplitToolAction('selectionCursor', 'selection brush cursor toggle')
    state.canvasFit = false
    state.canvasZoom = 1.28
    render()
    syncSplitWorkspace()
