    startMaskEditor()
    await new Promise((resolve) => window.setTimeout(resolve, 70))
    assertMaskEntryLayerVisibleBeforeLiveCanvas()
    window.__novaflowMaskSessionDebugDelayMs = 0
    await new Promise((resolve) => window.setTimeout(resolve, 360))
    if (!state.maskEditor || !state.maskEditor.active || state.viewMode !== 'maskEdit') throw new Error('mask editor did not start')
    assertNoVisibleSplitToolAction('maskCursor', 'mask brush cursor toggle')
    const maskCanvas = await movePointerOnActiveSplitCanvas()
    await assertMaskCursorVisible('mask editor')
    await assertBrushCursorHiddenOutsideCanvas('mask editor', '[data-novaflow-mask-brush-cursor="1"]')
    if (visiblePixelsOnCanvas(maskCanvas, 8) < 3000) throw new Error('mask editor canvas rendered empty')
    await paintMaskQuickColdStrokeOnActiveSplitCanvas()
    await new Promise((resolve) => window.setTimeout(resolve, 180))
    await paintMaskStrokeRealtimeOnActiveSplitCanvas()
