  function prepareSplitCanvasPanFixture(mode) {
    if (splitCanvasPanFixtureDone) return
    splitCanvasPanFixtureDone = true
    state.source = { fileName: 'pan-fixture.png', name: 'pan-fixture.png', dataUrl: splitCanvasPanSmokeSourceDataUrl() }
    state.sourceSize = { width: 360, height: 520 }
    state.canvasFit = true
    state.canvasZoom = 1
    state.canvasPanX = 0
    state.canvasPanY = 0
    resetMaskEditor()
    resetSelectionTool()
    if (mode === 'tool') {
      state.viewMode = 'selectionTool'
      state.selectionTool = {
        active: true,
        mode: 'cutout',
        cutoutSource: 'original',
        brushSize: 72,
        feather: 0,
        paintMode: 'draw',
        painting: false,
        cursor: null,
        showCursor: true,
        maskDataUrl: ''
      }
    } else {
      state.viewMode = 'source'
    }
    setMessage('PAN_TRACE_READY')
    render()
    syncSplitWorkspace()
  }

  function dispatchSplitCanvasPanSmokeMouse(target, type, x, y, buttons, movementX, movementY) {
    const event = new MouseEvent(type, {
      bubbles: true,
      cancelable: true,
      button: 2,
      buttons,
      which: 3,
      clientX: x,
      clientY: y,
      screenX: x,
      screenY: y
    })
    if (Number(movementX) || Number(movementY)) {
      window.__novaflowSplitPanSmokeMovement = { type, x: Number(movementX) || 0, y: Number(movementY) || 0 }
      event.__novaflowMovementX = Number(movementX) || 0
      event.__novaflowMovementY = Number(movementY) || 0
      try { Object.defineProperty(event, 'movementX', { configurable: true, value: Number(movementX) || 0 }) } catch {}
      try { Object.defineProperty(event, 'movementY', { configurable: true, value: Number(movementY) || 0 }) } catch {}
    }
    target.dispatchEvent(event)
  }

  async function runSplitCanvasPanSmokeTest() {
    if (splitCanvasPanSmokeDone) return
    splitCanvasPanSmokeDone = true
    state.source = { fileName: 'pan-smoke.png', name: 'pan-smoke.png', dataUrl: splitCanvasPanSmokeSourceDataUrl() }
    state.sourceSize = { width: 360, height: 520 }
    state.canvasFit = true
    state.canvasZoom = 1
    state.canvasPanX = 0
    state.canvasPanY = 0
    resetMaskEditor()
    resetSelectionTool()
    state.viewMode = 'source'
    setMessage('PAN_SMOKE_READY')
    render()
    syncSplitWorkspace()
    await new Promise((resolve) => window.setTimeout(resolve, 120))
    const overlay = splitCanvasOverlayElement()
    const target = overlay && (overlay.querySelector('[data-novaflow-split-canvas-scroll="1"]') || overlay)
    const art = overlay && overlay.querySelector('[data-novaflow-split-canvas-art="1"]')
    if (!target || !art) throw new Error('pan smoke target missing')
    const rect = target.getBoundingClientRect()
    const x = rect.left + Math.max(8, Math.min(rect.width - 8, rect.width * 0.52))
    const y = rect.top + Math.max(8, Math.min(rect.height - 8, rect.height * 0.52))
    dispatchSplitCanvasPanSmokeMouse(target, 'mousedown', x, y, 2)
    dispatchSplitCanvasPanSmokeMouse(target, 'mousemove', x + 96, y + 48, 4)
    dispatchSplitCanvasPanSmokeMouse(window, 'mousemove', x + 96, y + 48, 4)
    dispatchSplitCanvasPanSmokeMouse(window, 'mouseup', x + 96, y + 48, 0)
    await new Promise((resolve) => window.setTimeout(resolve, 80))
    const dx = Math.round(Number(state.canvasPanX) || 0)
    const dy = Math.round(Number(state.canvasPanY) || 0)
    const transform = String(art.style.transform || '')
    if (Math.abs(dx) < 70 || Math.abs(dy) < 32 || !transform.includes('translate')) {
      throw new Error(`pan smoke did not move dx=${dx} dy=${dy} transform=${transform}`)
    }
    document.body.setAttribute('data-novaflow-split-pan-smoke', `ok:${dx}:${dy}`)
    setMessage(`PAN_SMOKE_OK dx=${dx} dy=${dy}`)
    render()
    syncSplitWorkspace()
  }

